import{_ as l,a0 as t,w as o,s as d,ao as r,I as p,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何识别 Linux 上的文件分身 | LCTT x X-CMD","titleTemplate":false,"description":"如何识别 Linux 上的文件分身 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何识别 Linux 上的文件分身 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何识别 Linux 上的文件分身 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190415 How to identify duplicate files on Linux","title":"如何识别 Linux 上的文件分身","tag":"201904","desc":""},"relativePath":"201904/20190415 How to identify duplicate files on Linux.md","filePath":"[post].md"}'),h={name:"201904/20190415 How to identify duplicate files on Linux.md"};function c(u,s,g,f,k,m){const a=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何识别-linux-上的文件分身" tabindex="-1">如何识别 Linux 上的文件分身 <a class="header-anchor" href="#如何识别-linux-上的文件分身" aria-label="Permalink to “如何识别 Linux 上的文件分身”">​</a></h1><blockquote><p>Linux 系统上的一些文件可能出现在多个位置。按照本文指示查找并识别这些“同卵双胞胎”，还可以了解为什么硬链接会如此有利。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/reflections-candles-100793651-large.jpg" alt="Archana Jarajapu CC BY 2.0"></p><p>识别使用同一个磁盘空间的文件依赖于利用文件使用相同的 inode 这一事实。这种数据结构存储除了文件名和内容之外的所有信息。如果两个或多个文件具有不同的名称和文件系统位置，但共享一个 inode，则它们还共享内容、所有权、权限等。</p><p>这些文件通常被称为“硬链接”，不像符号链接（即软链接）那样仅仅通过包含它们的名称指向其他文件，符号链接很容易在文件列表中通过第一个位置的 <code>l</code> 和引用文件的 <code>-&gt;</code> 符号识别出来。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l my*</span></span>
<span class="line"><span>-rw-r--r-- 4 shs shs   228 Apr 12 19:37 myfile</span></span>
<span class="line"><span>lrwxrwxrwx 1 shs shs     6 Apr 15 11:18 myref -&gt; myfile</span></span>
<span class="line"><span>-rw-r--r-- 4 shs shs   228 Apr 12 19:37 mytwin</span></span></code></pre></div><p>在单个目录中的硬链接并不是很明显，但它仍然非常容易找到。如果使用 <code>ls -i</code> 命令列出文件并按 inode 编号排序，则可以非常容易地挑选出硬链接。在这种类型的 <code>ls</code> 输出中，第一列显示 inode 编号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -i | sort -n | more</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> 788000 myfile  &lt;==</span></span>
<span class="line"><span> 788000 mytwin  &lt;==</span></span>
<span class="line"><span> 801865 Name_Labels.pdf</span></span>
<span class="line"><span> 786692 never leave home angry</span></span>
<span class="line"><span> 920242 NFCU_Docs</span></span>
<span class="line"><span> 800247 nmap-notes</span></span></code></pre></div><p>扫描输出，查找相同的 inode 编号，任何匹配都会告诉你想知道的内容。</p><p>另一方面，如果你只是想知道某个特定文件是否是另一个文件的硬链接，那么有一种方法比浏览数百个文件的列表更简单，即 <code>find</code> 命令的 <code>-samefile</code> 选项将帮助你完成工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -samefile myfile</span></span>
<span class="line"><span>./myfile</span></span>
<span class="line"><span>./save/mycopy</span></span>
<span class="line"><span>./mytwin</span></span></code></pre></div><p>注意，提供给 <code>find</code> 命令的起始位置决定文件系统会扫描多少来进行匹配。在上面的示例中，我们正在查看当前目录和子目录。</p><p>使用 <code>find</code> 的 <code>-ls</code> 选项添加输出的详细信息可能更有说服力：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -samefile myfile -ls</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./myfile</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./save/mycopy</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./mytwin</span></span></code></pre></div><p>第一列显示 inode 编号，然后我们会看到文件权限、链接、所有者、文件大小、日期信息以及引用相同磁盘内容的文件的名称。注意，在这种情况下，链接字段是 “4” 而不是我们可能期望的 “3”。这告诉我们还有另一个指向同一个 inode 的链接（但不在我们的搜索范围内）。</p><p>如果你想在一个目录中查找所有硬链接的实例，可以尝试以下的脚本来创建列表并为你查找副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span># seaches for files sharing inodes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>prev=&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># list files by inode</span></span>
<span class="line"><span>ls -i | sort -n &gt; /tmp/$0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># search through file for duplicate inode #s</span></span>
<span class="line"><span>while read line</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    inode=\`echo $line | awk &#39;{print $1}&#39;\`</span></span>
<span class="line"><span>    if [ &quot;$inode&quot; == &quot;$prev&quot; ]; then</span></span>
<span class="line"><span>        grep $inode /tmp/$0</span></span>
<span class="line"><span>    fi</span></span>
<span class="line"><span>    prev=$inode</span></span>
<span class="line"><span>done &lt; /tmp/$0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># clean up</span></span>
<span class="line"><span>rm /tmp/$0</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./findHardLinks</span></span>
<span class="line"><span> 788000 myfile</span></span>
<span class="line"><span> 788000 mytwin</span></span></code></pre></div><p>你还可以使用 <code>find</code> 命令按 inode 编号查找文件，如命令中所示。但是，此搜索可能涉及多个文件系统，因此可能会得到错误的结果。因为相同的 inode 编号可能会在另一个文件系统中使用，代表另一个文件。如果是这种情况，文件的其他详细信息将不相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find / -inum 788000 -ls 2&gt; /dev/null</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /tmp/mycopy</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/myfile</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/save/mycopy</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/mytwin</span></span></code></pre></div><p>注意，错误输出被重定向到 <code>/dev/null</code>，这样我们就不必查看所有 “Permission denied” 错误，否则这些错误将显示在我们不允许查看的其他目录中。</p><p>此外，扫描包含相同内容但不共享 inode 的文件（即，简单的文本拷贝）将花费更多的时间和精力。</p><hr>`,23)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3387961/how-to-identify-duplicate-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3387961/how-to-identify-duplicate-files-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),e(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[4]||(s[4]=[n("MjSeven",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const x=l(h,[["render",c]]);export{w as __pageData,x as default};
